from pathlib import Path

p=Path('client/src/pages/Admin.tsx')
s=p.read_text()
old='''<div className="sale-question"><strong>Venda rápida</strong><span>Ao confirmar, o equipamento sai dos disponíveis, permanece no histórico e o termo de garantia será aberto automaticamente.</span></div><label className="admin-field sale-price-field">'''
new='''<div className="sale-question"><strong>Venda rápida</strong><span>Preencha os dados abaixo. Ao confirmar, o equipamento sai dos disponíveis, permanece no histórico e o controle de garantia fica pronto para o próximo passo.</span></div><div className="sale-flow-summary" aria-live="polite"><div><span>Equipamento</span><strong>{productToRemove.brand} {productToRemove.model}</strong></div><div><span>Vendedor</span><strong>{(sellerUsersQuery.data ?? []).find((seller) => String(seller.id) === saleSellerId)?.name || "Selecione abaixo"}</strong></div><div><span>Pagamento</span><strong>{salePaymentMethod || "Selecione abaixo"}</strong></div></div><div className="sale-flow-step"><span>1</span><strong>Dados da venda</strong><small>Confirme o valor, o vendedor e o pagamento.</small></div><label className="admin-field sale-price-field">'''
if old not in s: raise SystemExit('sale question markup not found')
s=s.replace(old,new)
s=s.replace('<div className="confirm-modal-actions sale-choice-actions"><button className="admin-secondary" onClick={() => setProductToRemove(null)}>Cancelar</button><button className="admin-secondary" disabled={removeMutation.isPending} onClick={() => confirmRemoval(false)}><Archive size={15} /> {removeMutation.isPending ? "Salvando..." : "Não, só ocultar"}</button><button className="remove-confirm-button" disabled={removeMutation.isPending} onClick={() => confirmRemoval(true)}><Check size={15} /> {removeMutation.isPending ? "Salvando..." : "Sim, foi vendido"}</button></div>', '<div className="confirm-modal-actions sale-choice-actions"><button className="admin-secondary sale-cancel-action" onClick={() => setProductToRemove(null)}>Cancelar</button><button className="admin-secondary sale-hide-action" disabled={removeMutation.isPending} onClick={() => confirmRemoval(false)}><Archive size={15} /> {removeMutation.isPending ? "Salvando..." : "Não, só ocultar"}</button><button className="remove-confirm-button sale-confirm-action" disabled={removeMutation.isPending} onClick={() => confirmRemoval(true)}><Check size={15} /> {removeMutation.isPending ? "Salvando..." : "Sim, foi vendido"}</button></div>')
p.write_text(s)

p=Path('client/src/index.css')
s=p.read_text()
s += '''\n\n/* Fluxo de venda e uso no celular: resumo curto, ação principal evidente e alvos confortáveis. */\n.sale-flow-summary { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin: 14px 0 16px; padding: 10px; border: 1px solid rgba(62, 190, 226, .2); border-radius: 12px; background: rgba(9, 39, 57, .55); }\n.sale-flow-summary div { min-width: 0; display: grid; gap: 3px; }\n.sale-flow-summary span { color: #83aebb; font-size: 10px; text-transform: uppercase; letter-spacing: .08em; }\n.sale-flow-summary strong { overflow: hidden; color: #eaf9fd; font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }\n.sale-flow-step { display: flex; align-items: center; gap: 8px; margin: 2px 0 10px; color: #dff7ff; }\n.sale-flow-step > span { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; color: #062033; background: #35c2f3; font-size: 11px; font-weight: 800; }\n.sale-flow-step strong { font-size: 12px; }\n.sale-flow-step small { color: #8eafbf; font-size: 11px; }\n.sale-confirm-action { box-shadow: 0 8px 20px rgba(0, 157, 215, .2); }\n@media (max-width: 760px) {\n  .sale-confirm-modal { max-height: calc(100dvh - 24px); overflow-y: auto; padding: 18px 15px; }\n  .sale-flow-summary { grid-template-columns: 1fr; gap: 7px; }\n  .sale-flow-summary div { grid-template-columns: 86px minmax(0, 1fr); align-items: center; }\n  .sale-flow-summary strong { white-space: normal; }\n  .sale-flow-step { align-items: flex-start; flex-wrap: wrap; }\n  .sale-flow-step small { flex-basis: calc(100% - 30px); margin-left: 30px; margin-top: -5px; }\n  .sale-choice-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }\n  .sale-choice-actions button { width: 100%; min-height: 48px; }\n  .sale-confirm-action { grid-column: 1 / -1; grid-row: 1; min-height: 52px !important; font-size: 13px; }\n  .sale-cancel-action { grid-column: 1; grid-row: 2; }\n  .sale-hide-action { grid-column: 2; grid-row: 2; }\n}\n@media (max-width: 420px) {\n  .admin-operational-actions { grid-template-columns: 1fr 1fr; }\n  .admin-operational-actions .operational-action { min-height: 46px; padding-inline: 8px; font-size: 11px; }\n  .admin-shell .inventory-row > .inventory-actions { gap: 8px; }\n  .admin-shell .inventory-actions > button { min-height: 48px; }\n}\n'''
p.write_text(s)

p=Path('server/sell-workflow.test.ts')
s=p.read_text()
needle='expect(admin).toContain("Relatório geral de vendas");'
if needle in s and 'sale-flow-summary' not in s:
 s=s.replace(needle, needle+'\n    expect(admin).toContain("sale-flow-summary");\n    expect(admin).toContain("sale-confirm-action");')
